public protocol DatabaseProtocol: AnyObject, Sendable {
    
    func blob(id: String) async throws  -> WireBlobSnapshot
    
    func discardBlob(id: String) async throws 
    
    func retryBlob(id: String) async throws 
    
    func uploadBlob(name: String, create: String, request: WireUploadRequest) async throws  -> WireBlobSnapshot
    
    func waitBlob(id: String) async throws  -> String
    
    /**
     * Waits for the one outcome of the command: delivered, refused, or ended with its session. It waits also while the network is away and the command is queued.
     */
    func commandOutcome(receipt: CommandReceipt) async throws  -> CommandStatus
    
    /**
     * The status of the command now. A receipt of an epoch that has gone is `Ended`, also when the epoch moves while the row is read.
     */
    func commandStatus(receipt: CommandReceipt) throws  -> CommandStatus
    
    /**
     * Writes the row locally in the epoch of the caller and queues it for the server. The SQL commit is refused when the epoch moved or the database closed before it.
     */
    func send(request: CommandRequest) async throws  -> CommandReceipt
    
    func act(model: String, rowId: String, action: String, patchJson: String, argsJson: String) async throws  -> QueuedAction
    
    func answer(model: String, operation: Int64) async throws  -> String
    
    func attach(model: String, rowId: String, field: String, bytes: Data, name: String, mime: String) async throws  -> String
    
    func cancelUpload(model: String, rowId: String, action: String) async throws  -> Bool
    
    /**
     * Closes the database: every lease ends, every holder closes, the process slot opens for the next database. Closing again returns the same result. The name differs from `close` because Kotlin objects already carry `close()` for their native handle.
     */
    func closeDatabase() async throws 
    
    func confirmed(model: String, rowId: String) async throws  -> String
    
    /**
     * Writes a row that only this device keeps. A model whose create declares a server mutation is written by `send`.
     */
    func create(model: String, valuesJson: String, argsJson: String) async throws  -> WireRow
    
    func destroy(model: String, rowId: String) async throws 
    
    func detach(model: String, rowId: String, field: String) async throws  -> Bool
    
    func discard(model: String, rowId: String, action: String?) async throws 
    
    func edgeValues(model: String, relation: String, paramsJson: String, rowIds: [String]) async throws  -> String
    
    func enterForegroundForTesting() throws 
    
    func file(model: String, rowId: String, field: String) async throws  -> String?
    
    func flush() async throws 
    
    func load(model: String, relation: String, paramsJson: String) async throws 
    
    func loadAll(model: String, relation: String, paramsJson: String, force: Bool) async throws 
    
    func loadMore(model: String, relation: String, paramsJson: String) async throws  -> LoadMoreResult
    
    func maintain() async throws 
    
    func node(model: String, relation: String, rowId: String, force: Bool) async throws  -> WireRow?
    
    func nodes(model: String, relation: String, rowIds: [String]) async throws  -> [WireRow]
    
    func onlineSink() throws  -> OnlineSink
    
    func openReport()  -> OpenReport
    
    func peekRow(model: String, rowId: String) throws  -> WireRow?
    
    func read(model: String, rowId: String, field: String) async throws  -> Data?
    
    func refresh(model: String, relation: String, paramsJson: String) async throws 
    
    func refreshPreloads() async throws 
    
    func registerOperations(defsJson: String) throws 
    
    func resume() async throws 
    
    func resumeUploads() async throws 
    
    func retry(model: String, rowId: String, action: String?) async throws  -> UInt64
    
    func retryAll() async throws  -> UInt64
    
    func run(operation: String, variablesJson: String) async throws  -> String
    
    func setEphemeral(model: String, rowId: String, valuesJson: String) async throws 
    
    func setListening(allowed: Bool) throws 
    
    func setLocal(model: String, rowId: String, path: String, valueJson: String) async throws 
    
    func setOnline(online: Bool) throws 
    
    func settled(model: String, rowId: String, action: String?) async throws 
    
    func subscriptionCensus()  -> SubscriptionCensus
    
    func update(model: String, rowId: String, patchJson: String, argsJson: String) async throws  -> WireRow
    
    func upload(epoch: UInt64, model: String, rowId: String, action: String, request: WireUploadRequest) async throws  -> Int64
    
    func uploadCreateBatch(epoch: UInt64, model: String, items: [WireUploadItem], request: WireUploadBatch) async throws  -> [WireRow]
    
    func url(model: String, rowId: String, field: String) async throws  -> String?
    
    func warm(queryJson: String) async throws 
    
    func sessionCall(operation: String, bodyJson: String) async throws  -> String
    
    /**
     * Ends the session: the old work ends, the credential and the data of the account go. Returns after the clearing. The same call ends a plain or local database too.
     */
    func sessionReset() async throws 
    
    func sessionResume() async throws  -> String?
    
    /**
     * The reader stopped. The stream ends in the core and nothing is delivered after this call returns.
     */
    func cancelStream(stream: UInt64) 
    
    /**
     * Loads the next page of the relation of the stream.
     */
    func loadMoreStream(stream: UInt64) async throws  -> LoadMoreResult
    
    /**
     * The rows of a query the core already holds, without a stream and without reading SQLite on the calling thread.
     */
    func peekQuery(queryJson: String) async throws  -> CachedQuery?
    
    /**
     * Loads the relation of the stream again from the server. The answer belongs to the epoch of the stream: it ends as `Interrupted` when the session changed.
     */
    func refreshStream(stream: UInt64) async throws 
    
    /**
     * The reader could not apply a delta (its revision is not the delta's base). The core sends one new snapshot.
     */
    func resyncStream(stream: UInt64) 
    
    /**
     * The epoch of the session now. A reader that opens streams for an account asks for it once, after the sign-in, and hands it to every stream and command of that account.
     */
    func sessionEpoch()  -> UInt64
    
    func streamCensus()  -> StreamCensus
    
    /**
     * Returns when the first load of the stream settled. Fails when the epoch of the stream ended first.
     */
    func streamLoaded(stream: UInt64) async throws 
    
    /**
     * Opens a stream and returns its number at once. The first value arrives as a snapshot, then deltas follow. A stream opened for an epoch that has gone ends with one `Ended` value.
     */
    func subscribe(epoch: UInt64, request: StreamRequest, sink: ValueSink)  -> UInt64
    
    func backgroundRefused(items: [WireAcceptedUpload], detail: String) throws 
    
    func roundAbandon(owner: UInt32) 
    
    func roundBegin()  -> UInt32?
    
    func roundEnd(owner: UInt32)  -> [WireAcceptedUpload]?
    
    func roundLeave(owner: UInt32)  -> WireRoundStep
    
    func roundNext(owner: UInt32)  -> WireRoundStep
    
    func setUploadAcceptedSink(sink: UploadAcceptedSink) 
    
}
