            } catch {
                print("Uniffi callback interface Transport: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTransport.handleMap.clone(handle: uniffiHandle)
            } catch {
